sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_fcFloor;
uniform float amzp_fcFloorY;
uniform float amzp_fcClip;
uniform float amzp_fcSceneLight;
uniform float amzp_fcLightAng;
uniform float amzp_fcLightHt;
uniform float amzp_fcShOn;
layout(color) uniform half4 amzp_fcShCol;
uniform float amzp_fcShOpa;
uniform float amzp_fcShSoft;
uniform float amzp_fcShFade;
uniform float amzp_fcCtOn;
uniform float amzp_fcCtOpa;
uniform float amzp_fcCtSize;
uniform float amzp_fcRfOn;
uniform float amzp_fcRfOpa;
uniform float amzp_fcRfFade;
uniform float amzp_fcRfBlur;
uniform float amzp_fcQuality;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    uniform float4x4 nmFloorM;
    uniform float4 nmFloorP;
    uniform float nmLightN;
    uniform float4 nmLightP[4];
    uniform float4 nmLightD[4];
    uniform float4 nmLightC[4];
    float3 CP;
    float GPS;
    float4x4 FM;
    float FY;
    float4 FLIM;
    float3 LO, LN, LU, LV;
    float camOK() { return (nmProj[2][3] > 0.5 && abs(nmProj[0][0]) + abs(nmProj[1][1]) > 1e-6) ? 1.0 : 0.0; }
    float3 rayDir(float2 q) {
        float3 r0 = float3(nmProj[0][0], nmProj[1][0], nmProj[2][0]);
        float3 r1 = float3(nmProj[0][1], nmProj[1][1], nmProj[2][1]);
        float3 rw = float3(nmProj[0][3], nmProj[1][3], nmProj[2][3]);
        float3 d = cross(r0 - q.x * rw, r1 - q.y * rw);
        if (d.z < 0.0) d = -d;
        float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
        float3 w = float3(dot(c0, d) / max(dot(c0, c0), 1e-8), dot(c1, d) / max(dot(c1, c1), 1e-8), dot(c2, d) / max(dot(c2, c2), 1e-8));
        return normalize(w);
    }
    float3 camPos() {
        float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
        float3 t = nmView[3].xyz;
        return -float3(dot(c0, t) / max(dot(c0, c0), 1e-8), dot(c1, t) / max(dot(c1, c1), 1e-8), dot(c2, t) / max(dot(c2, c2), 1e-8));
    }
    float2 toUv(float3 w) {
        float4 c = nmProj * (nmView * float4(w, 1.0));
        if (c.w <= 1e-3) return float2(-9.0);
        float2 q = c.xy / c.w;
        float2 pix = q * GPS + screen.zw * 0.5;
        return float2(pix.x / screen.zw.x, 1.0 - pix.y / screen.zw.y);
    }
    float4 layerAt(float3 w) {
        float2 uv = toUv(w);
        if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, uv);
    }
    float taps() { return int(amzp_fcQuality) == 0 ? 6.0 : (int(amzp_fcQuality) == 1 ? 12.0 : 20.0); }
    float4 layerBlur(float3 w, float r) {
        if (r < 0.75) return layerAt(w);
        float4 s = layerAt(w);
        float n = 1.0;
        float T = taps();
        for (int i = 0; i < 20; i++) {
            float fi = float(i);
            if (fi >= T) break;
            float a = fi * 2.39996323;
            float rr = r * sqrt((fi + 0.5) / T);
            s += layerAt(w + (LU * cos(a) + LV * sin(a)) * rr);
            n += 1.0;
        }
        return s / n;
    }
    void amzRender() {
        float4 orig = amzTexture(0, amzScreenNorm());
        if (camOK() < 0.5) { amzOutput = orig; return; }
        GPS = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        float2 q = (pix - screen.zw * 0.5) / GPS;
        CP = camPos();
        float3 rd = rayDir(q);
        if (int(amzp_fcFloor) == 0 && nmFloorP.x > 0.5) { FM = nmFloorM; FY = nmFloorP.y; FLIM = float4(nmFloorP.zw, 0.0, 0.0); }
        else { FM = float4x4(1.0); FY = amzp_fcFloorY; FLIM = float4(0.0); }
        float3 fx = FM[0].xyz, fyv = FM[1].xyz, fz = FM[2].xyz;
        float3 ND = normalize(fyv);
        float3 UP = -ND;
        float3 PF = (FM * float4(0.0, FY, 0.0, 1.0)).xyz;
        float3 XR = normalize(fx), ZR = normalize(fz);
        LO = nmModel[3].xyz;
        LU = normalize(nmModel[0].xyz);
        LV = normalize(nmModel[1].xyz);
        LN = normalize(cross(nmModel[0].xyz, nmModel[1].xyz));
        float den = dot(rd, ND);
        float4 F = float4(0.0);
        if (abs(den) > 1e-6) {
            float t = dot(PF - CP, ND) / den;
            if (t > 0.0) {
                float3 P = CP + rd * t;
                bool inside = true;
                if (FLIM.x > 0.0 || FLIM.y > 0.0) {
                    float3 d = P - PF;
                    float rx = dot(d, fx) / max(dot(fx, fx), 1e-8);
                    float rz = dot(d, fz) / max(dot(fz, fz), 1e-8);
                    if (FLIM.x > 0.0 && abs(rx) > FLIM.x) inside = false;
                    if (FLIM.y > 0.0 && abs(rz) > FLIM.y) inside = false;
                }
                if (inside) {
                    float sh = 0.0;
                    if ((amzp_fcShOn>0.5)) {
                        float ha = radians(clamp(amzp_fcLightHt, 1.0, 89.9)), aa = radians(amzp_fcLightAng);
                        float3 LD = normalize(cos(ha) * (sin(aa) * XR - cos(aa) * ZR) + sin(ha) * UP);
                        if ((amzp_fcSceneLight>0.5) && nmLightN > 0.5) {
                            for (int i = 0; i < 4; i++) {
                                if (float(i) >= nmLightN) break;
                                if (nmLightC[i].w > 0.5) {
                                    float3 to = nmLightP[i].w > 0.5 ? nmLightP[i].xyz - P : -nmLightD[i].xyz;
                                    if (dot(to, to) > 1e-6 && dot(normalize(to), UP) > 0.02) LD = normalize(to);
                                    break;
                                }
                            }
                        }
                        float dn = dot(LD, LN);
                        if (abs(dn) > 1e-5) {
                            float s = dot(LO - P, LN) / dn;
                            if (s > 0.0) {
                                float3 X = P + LD * s;
                                float a = layerBlur(X, amzp_fcShSoft * s * 0.12).a;
                                sh = a * clamp(amzp_fcShOpa, 0.0, 1.0) * exp(-s / max(amzp_fcShFade, 1.0));
                            }
                        }
                    }
                    if ((amzp_fcCtOn>0.5)) {
                        float dd = dot(P - LO, LN);
                        float3 Xc = P - LN * dd;
                        float cs = max(amzp_fcCtSize, 1.0);
                        float a = layerAt(Xc + UP * cs * 0.1).a * 0.5 + layerAt(Xc + UP * cs * 0.35).a * 0.3 + layerAt(Xc + UP * cs * 0.8).a * 0.2;
                        float ct = a * exp(-abs(dd) / (cs * 0.6)) * clamp(amzp_fcCtOpa, 0.0, 1.0);
                        sh = 1.0 - (1.0 - sh) * (1.0 - ct);
                    }
                    F = float4(amzp_fcShCol.rgb, 1.0) * sh;
                    if ((amzp_fcRfOn>0.5)) {
                        float3 rr = reflect(rd, ND);
                        float dn = dot(rr, LN);
                        if (abs(dn) > 1e-5) {
                            float s = dot(LO - P, LN) / dn;
                            float3 X = P + rr * s;
                            if (s > 0.0 && dot(X - PF, ND) < 0.5) {
                                float4 c = layerBlur(X, amzp_fcRfBlur * s * 0.08);
                                c *= clamp(amzp_fcRfOpa, 0.0, 1.0) * exp(-s / max(amzp_fcRfFade, 1.0));
                                F = c + F * (1.0 - c.a);
                            }
                        }
                    }
                }
            }
        }
        if ((amzp_fcClip>0.5)) {
            float dl = dot(rd, LN);
            float dn2 = dot(rd, ND);
            if (abs(dl) > 1e-6) {
                float tl = dot(LO - CP, LN) / dl;
                if (tl > 0.0) {
                    float3 X = CP + rd * tl;
                    float sx = dot(X - PF, ND), sc = dot(CP - PF, ND);
                    float pw = max(0.75, 0.75 * tl / max(abs(nmProj[0][0]), 1e-3));
                    float opp = sc < 0.0 ? smoothstep(-pw, pw, sx) : smoothstep(-pw, pw, -sx);
                    float inb = 0.0;
                    if (opp > 0.0 && abs(dn2) > 1e-6) {
                        float tf = dot(PF - CP, ND) / dn2;
                        if (tf > 0.0 && tf < tl + pw) {
                            float3 Pf = CP + rd * tf;
                            float3 d = Pf - PF;
                            float rx = dot(d, fx) / max(dot(fx, fx), 1e-8);
                            float rz = dot(d, fz) / max(dot(fz, fz), 1e-8);
                            inb = 1.0;
                            if (FLIM.x > 0.0 && abs(rx) > FLIM.x) inb = 0.0;
                            if (FLIM.y > 0.0 && abs(rz) > FLIM.y) inb = 0.0;
                        }
                    }
                    orig *= 1.0 - opp * inb;
                }
            }
        }
        amzOutput = orig + F * (1.0 - orig.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
